<template><aside v-if="context" class="diario-reminders" aria-label="Recordatorios de actividades">
 <div class="diario-fish" :class="{talking}" v-if="fishVisible || talking"><img :src="talking?'static/images/ali-goldfish-talking.svg':'static/images/ali-goldfish.svg'" alt="ALI, pececito dorado"><span>{{talking?'Hablando':'ALI te acompaña'}}</span></div><div v-if="canControlVoice" class="diario-voice-controls"><div class="diario-voice-state"><button type="button" class="diario-reminder-toggle" role="switch" :aria-checked="enabled?'true':'false'" aria-label="Activar voz de recordatorios de ALI" @click="toggle"><span class="diario-switch-track" :class="{'is-on':enabled}" aria-hidden="true"><span></span></span><span class="diario-switch-label"><strong>♩ Voz de ALI</strong><small>{{enabled?'ACTIVADA':'DESACTIVADA'}}</small></span></button><span class="diario-switch-status" role="status">{{enabled?'Recordatorios por voz activados':'Desactivado'}}</span></div><button type="button" class="diario-voice-settings" aria-label="Elegir voz de ALI" title="Elegir y probar voz" @click="voiceOpen=!voiceOpen" :aria-expanded="voiceOpen?'true':'false'">⚙ ALI</button></div><section v-if="canControlVoice && voiceOpen" class="diario-voice-panel"><strong>Voz de ALI</strong><label>Voz del equipo<select v-model="voiceChoice" @change="saveVoice"><option value="">Automática en español</option><option v-for="v in voices" :key="v.voiceURI" :value="v.voiceURI">{{v.name}} ({{v.lang}})</option></select></label><p v-if="!voices.length">El navegador todavía no tiene voces disponibles.</p><button type="button" @click="previewVoice" :disabled="!speechAvailable">Probar voz</button><button type="button" @click="stopAudio">Detener</button><button type="button" @click="voiceOpen=false">Cerrar</button><p v-if="!speechAvailable">Este navegador no admite lectura por voz.</p></section>
 <section v-if="notice" class="diario-reminder-card" role="status"><strong>ALI · Tu diario</strong><p>{{notice}}</p><p class="diario-encouragement">{{departing?'Te dejo continuar. Gracias por tu esfuerzo, ¡tú puedes!':'Vamos paso a paso. Cada avance cuenta, ¡sigue adelante!'}}</p><small>Este aviso se cierra en 15 segundos.</small><a href="/views/diario.php" target="_top">Ver actividades</a><button type="button" @click="dismissNotice">Cerrar</button></section>
</aside></template>
<script>
import config from '@/store/config.js';
import {reminderPhase} from '@/utils/diario';
export default {
 data(){return {departing:false,fishVisible:false,voices:[],voiceChoice:'',voiceOpen:false,talking:false,speechAvailable:!!window.speechSynthesis,context:null,enabled:false,notice:'',polling:false,dictating:false}},
 mounted(){this.loadVoices();this._voices=()=>this.loadVoices();if(window.speechSynthesis)window.speechSynthesis.addEventListener('voiceschanged',this._voices);this.init();this._focus=()=>this.poll();this._dictation=active=>{this.dictating=active;if(active)this.stopAudio()};window.addEventListener('focus',this._focus);this.$root.$on('diario:changed',this.poll);this.$root.$on('diario:motivation',this.celebrate);this.$root.$on('diario:dictation',this._dictation)},
 beforeDestroy(){clearTimeout(this._noticeTimer);clearTimeout(this._farewellTimer);clearTimeout(this._fishTimer);if(window.speechSynthesis)window.speechSynthesis.removeEventListener('voiceschanged',this._voices);clearInterval(this._timer);window.removeEventListener('focus',this._focus);this.$root.$off('diario:changed',this.poll);this.$root.$off('diario:motivation',this.celebrate);this.$root.$off('diario:dictation',this._dictation);this.stopAudio()},
 computed:{canReceiveReminders(){return !!this.context&&(this.context.programador||this.context.superadmin);},canControlVoice(){return !!this.context && String(this.context.user || '').toLowerCase() === 'superadmin';}},
 methods:{
 dismissNotice(){clearTimeout(this._noticeTimer);clearTimeout(this._farewellTimer);this.notice='';this.departing=false;this.stopAudio()},
 announce(text){if(!this.canReceiveReminders)return;this.dismissNotice();this.notice=text;this.fishVisible=true;this._farewellTimer=setTimeout(()=>{this.departing=true},12000);this._noticeTimer=setTimeout(()=>this.dismissNotice(),15000);this.speak(text+' Gracias por tu esfuerzo. Paso a paso, puedes lograrlo.')},
 showFish(){clearTimeout(this._fishTimer);this.fishVisible=true;this._fishTimer=setTimeout(()=>{this.fishVisible=false},10000)},
 loadVoices(){this.voices=window.speechSynthesis?window.speechSynthesis.getVoices().slice().sort((a,b)=>Number(/^es/i.test(b.lang))-Number(/^es/i.test(a.lang))||a.name.localeCompare(b.name)):[]},
 saveVoice(){if(this.context)try{localStorage.setItem('diario:voiceChoice:'+this.context.user,this.voiceChoice)}catch(e){}this.stopAudio()},
 previewVoice(){this.stopAudio();this.speak('Hola, soy ALI. Te acompa\u00f1o con tus actividades y recordatorios.',true)},
  async init(){try{const r=await this.axios.get(config.API+'diario/contexto?ligero=1',{timeout:10000});if(!r.data.programador&&!r.data.superadmin){this.context=null;this.enabled=false;this.dismissNotice();return;}this.context=r.data;try{this.enabled=localStorage.getItem('diario:voice:'+this.context.user)==='1';this.voiceChoice=localStorage.getItem('diario:voiceChoice:'+this.context.user)||''}catch(e){}this._timer=setInterval(this.poll,60000);this.poll()}catch(e){}},
  toggle(){if(!this.canControlVoice)return;this.enabled=!this.enabled;try{localStorage.setItem('diario:voice:'+this.context.user,this.enabled?'1':'0')}catch(e){}if(this.enabled){this.speak('Avisos de ALI activados. Te recordaré tus actividades mientras el sistema esté abierto.');this.poll()}else this.stopAudio()},
  stopAudio(){clearTimeout(this._fishTimer);this.fishVisible=false;this.talking=false;if(this._utterance&&window.speechSynthesis){window.speechSynthesis.cancel();this._utterance=null}},
  speak(text,preview=false){if(!this.canReceiveReminders||(!this.enabled&&!preview)||!window.speechSynthesis||document.hidden||this.dictating)return;const host=document.querySelector('.ali-host'),ali=host&&host.__vue__;if(ali&&(ali.busy||ali.listening||ali._recognition||ali._wakeRecognition))return;if(window.speechSynthesis.speaking||window.speechSynthesis.pending)return;const u=new SpeechSynthesisUtterance(text);const selected=this.voices.find(v=>v.voiceURI===this.voiceChoice)||this.voices.find(v=>/^es[-_]PE/i.test(v.lang))||this.voices.find(v=>/^es/i.test(v.lang));u.lang=selected?selected.lang:'es-PE';if(selected)u.voice=selected;u.rate=1.05;u.onstart=()=>{clearTimeout(this._fishTimer);this.fishVisible=true;this.talking=true};u.onend=u.onerror=()=>{if(this._utterance===u){this.talking=false;this.fishVisible=!!this.notice;this._utterance=null}};this._utterance=u;window.speechSynthesis.speak(u)},
  celebrate(text){this.announce(text)},
  async poll(){if(!this.canReceiveReminders||this.polling||document.hidden)return;this.polling=true;try{
   const r=await this.axios.get(config.API+'diario/recordatorios',{timeout:10000});const now=Date.parse(r.data.ahora.replace(' ','T')+'-05:00');const due=[];
   for(const t of r.data.tareas){const phase=reminderPhase(t,now);if(!phase)continue;const key='diario:notice:'+this.context.user+':'+(t.Tipo||'laboral')+':'+t.Id+':'+phase;let last=0;try{last=Number(localStorage.getItem(key))||0}catch(e){}if(now-last<Number(t.Frecuencia)*60000)continue;due.push({t,phase,key})}
   if(!due.length)return;const item=due[0];const labels={vencida:'tiene el plazo vencido',fin:'está cerca de su hora de fin',inicio:'está por comenzar',inicio_pendiente:'está pendiente de iniciar'};
   const message=item.t.Tipo==='personal'?'Tu recordatorio personal: '+item.t.Titulo+'.': 'La actividad «'+item.t.Titulo+'» '+labels[item.phase]+'.'+(due.length>1?' Tienes '+due.length+' actividades por revisar.':'')+' Tú puedes: avanza un paso a la vez.';
   // One digest per interval, shared between tabs for the same account.
   for(const d of due)try{localStorage.setItem(d.key,String(now))}catch(e){}
   this.announce(message);
  }catch(e){if(e.response&&[401,403].includes(e.response.status)){this.context=null;clearInterval(this._timer);this.stopAudio()}}finally{this.polling=false}}
 }
};
</script>
<style>
.diario-reminders{position:fixed;left:14px;bottom:12px;z-index:13900;font-family:Arial,sans-serif}.diario-reminder-toggle{border:1px solid #c5dbe6;border-radius:18px;padding:7px 12px;background:#f0f8fc;color:#19445d;font-size:11px;cursor:pointer;box-shadow:0 3px 12px #123e5620}.diario-reminder-card{position:fixed;top:130px;right:22px;bottom:auto;left:auto;width:310px;max-width:calc(100vw - 28px);padding:18px;background:white;border:1px solid #b6d9e8;border-left:5px solid #00a482;border-radius:14px;box-shadow:0 8px 32px #123e5633;color:#1d4056}.diario-reminder-card p{font-size:14px;line-height:1.5;margin:10px 0}.diario-reminder-card a{color:#007d75;font-weight:bold}.diario-reminder-card button{float:right;background:#eaf2f7;border:0;border-radius:6px;padding:5px 10px}
.diario-voice-settings{border:1px solid #c5dbe6;border-radius:18px;background:white;color:#19445d;padding:7px 12px;font-size:11px;margin-right:5px;cursor:pointer}.diario-voice-panel{position:absolute;bottom:48px;left:0;width:310px;max-width:calc(100vw - 28px);background:#fff;color:#193d57;border:1px solid #caddeb;border-radius:16px;padding:17px;box-shadow:0 12px 36px #18365330;z-index:2}.diario-voice-panel label{display:block;margin:12px 0}.diario-voice-panel select{display:block;width:100%;padding:9px;border:1px solid #b7cede;border-radius:8px;color:#193d57;background:white}.diario-voice-panel button{padding:7px 12px;border:1px solid #c5dbe6;border-radius:8px;background:#edf5fb;color:#19445d;margin:3px}.diario-voice-panel p{font-size:12px}.diario-fish{position:fixed;top:18px;right:22px;bottom:auto;left:auto;display:flex;align-items:center;flex-direction:column;pointer-events:none}.diario-fish img{width:100px;height:74px;animation:diarioFishFloat 3s ease-in-out infinite}.diario-fish span{background:#fff7d8;color:#72511b;border-radius:12px;padding:3px 9px;font-size:11px}.diario-fish.talking img{animation-duration:1s}@media(max-width:767px){.diario-fish{top:12px;right:12px}.diario-fish img{width:85px;height:63px}}@keyframes diarioFishFloat{50%{transform:translateY(-6px) rotate(-3deg)}}@media(prefers-reduced-motion:reduce){.diario-fish img{animation:none}}
.diario-encouragement{color:#16735e;font-weight:600}.diario-reminder-card>small{display:block;color:#627b8d;font-size:11px;margin-bottom:12px}@media(max-width:767px){.diario-reminder-card{top:112px;right:12px;max-height:calc(100vh - 180px);overflow:auto}}
.diario-reminders.pos-inline-voice{position:relative;left:auto;bottom:auto;z-index:auto;display:flex;flex-wrap:wrap;align-items:center;justify-content:flex-end;gap:7px;margin:12px 0 4px;width:100%}.pos-inline-voice .diario-voice-settings{margin:0}.pos-inline-voice .diario-voice-settings,.pos-inline-voice .diario-reminder-toggle{font-size:14px;min-height:42px;padding:9px 13px}.pos-inline-voice .diario-voice-panel{position:relative;bottom:auto;left:auto;order:3;width:100%;max-width:100%;margin-top:5px;text-align:left}
.diario-voice-controls{display:flex;align-items:flex-start;gap:10px;width:410px;max-width:calc(100vw - 28px)}.diario-voice-state{min-width:0;flex:1}.diario-voice-controls .diario-reminder-toggle{display:flex;align-items:center;gap:12px;width:100%;padding:12px 14px;min-height:64px;border:1px solid #c2d9ea;border-radius:16px;background:#e8f2fa;color:#21485f;text-align:left;box-shadow:0 4px 12px #1c466d12}.diario-switch-track{display:flex;align-items:center;flex-shrink:0;width:49px;height:27px;border-radius:20px;background:#b2c7d5;padding:3px;box-shadow:inset 0 1px 3px #25465a40;transition:background .18s}.diario-switch-track>span{display:block;width:21px;height:21px;border-radius:50%;background:white;box-shadow:0 1px 4px #234b6330;transition:transform .18s}.diario-switch-track.is-on{background:#16a38a}.diario-switch-track.is-on>span{transform:translateX(22px)}.diario-switch-label strong{display:block;font:700 15px/1.35 "Segoe UI",Arial,sans-serif}.diario-switch-label small{display:block;font:500 10px/1.5 "Segoe UI",Arial,sans-serif;letter-spacing:1.4px;margin-top:3px;color:#58798e}.diario-switch-status{display:block;font:12px/1.4 "Segoe UI",Arial,sans-serif;color:#31586d;margin-top:7px;padding-left:2px}.diario-voice-controls .diario-voice-settings{margin:0;min-width:82px;min-height:64px;border:1px solid #7b81cf;border-radius:16px;background:linear-gradient(120deg,#14567e,#5742c7);color:white;font:750 19px "Segoe UI",Arial,sans-serif;box-shadow:0 4px 12px #234d7320;padding:12px}.diario-voice-controls button:focus-visible{outline:3px solid #7b99e3;outline-offset:3px}.pos-inline-voice .diario-voice-controls{width:100%;max-width:100%}.pos-inline-voice .diario-voice-controls .diario-reminder-toggle{padding:10px;gap:8px}.pos-inline-voice .diario-voice-controls .diario-voice-settings{min-width:70px;padding:10px}.pos-inline-voice .diario-switch-label strong{font-size:14px}.diario-reminders:not(.pos-inline-voice) .diario-voice-panel{bottom:105px}@media(prefers-reduced-motion:reduce){.diario-switch-track,.diario-switch-track>span{transition:none}}
.diario-voice-controls>.diario-voice-settings{min-height:64px!important;font-size:19px!important}.diario-voice-controls .diario-reminder-toggle{min-height:64px!important}
</style>

<style>
@media print{.diario-reminders{display:none!important}}
</style>
